{
  "items": [
    {
      "name": "Polynomial.map_mod",
      "module_name": "Mathlib.Algebra.Polynomial.FieldDivision",
      "kind": "theorem",
      "type": "∀ {R : Type u} {k : Type y} [inst : Field R] {p q : Polynomial R} [inst_1 : Field k] (f : R →+* k),\n  Polynomial.map f (p % q) = Polynomial.map f p % Polynomial.map f q"
    },
    {
      "name": "Polynomial.map_modByMonic",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Ring R] {p q : Polynomial R} [inst_1 : Ring S] (f : R →+* S),\n  q.Monic → Polynomial.map f (p %ₘ q) = Polynomial.map f p %ₘ Polynomial.map f q"
    },
    {
      "name": "IsAdjoinRootMonic.map_modByMonic",
      "module_name": "Mathlib.RingTheory.IsAdjoinRoot",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : CommRing R] [inst_1 : Ring S] {f : Polynomial R} [inst_2 : Algebra R S]\n  (h : IsAdjoinRootMonic S f) (g : Polynomial R), h.map (g %ₘ f) = h.map g"
    },
    {
      "name": "Polynomial.map_divByMonic",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Ring R] {p q : Polynomial R} [inst_1 : Ring S] (f : R →+* S),\n  q.Monic → Polynomial.map f (p /ₘ q) = Polynomial.map f p /ₘ Polynomial.map f q"
    },
    {
      "name": "AdjoinRoot.mapAlgHom",
      "module_name": "Mathlib.RingTheory.AdjoinRoot",
      "kind": "definition",
      "type": "{R : Type u_1} →\n  {S : Type u_2} →\n    {T : Type u_3} →\n      [inst : CommRing R] →\n        [inst_1 : CommRing S] →\n          [inst_2 : CommRing T] →\n            [inst_3 : Algebra R S] →\n              [inst_4 : Algebra R T] →\n                (f : S →ₐ[R] T) →\n                  (p : Polynomial S) → (q : Polynomial T) → q ∣ Polynomial.map (↑f) p → AdjoinRoot p →ₐ[R] AdjoinRoot q"
    },
    {
      "name": "IsAdjoinRootMonic.modByMonicHom_map",
      "module_name": "Mathlib.RingTheory.IsAdjoinRoot",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : CommRing R] [inst_1 : Ring S] {f : Polynomial R} [inst_2 : Algebra R S]\n  (h : IsAdjoinRootMonic S f) (g : Polynomial R), h.modByMonicHom (h.map g) = g %ₘ f"
    }
  ]
}
